-- =====================================================================
-- Physical Change · V8 · Catálogo global de ejercicios con vídeo (PostgreSQL 16)
-- Origen: ejercicios_harbiz_youtube.csv (2129 ejercicios, todos con enlace de YouTube).
-- Añade a exercise los datos del catálogo y los inserta como ejercicios globales (owner_id NULL).
-- Mismo nombre ya existente como global: se omite (no duplica). No editar una vez desplegado.
--
-- Reversión manual:
--   DELETE FROM exercise WHERE owner_id IS NULL AND video_url IS NOT NULL
--     AND id NOT IN (SELECT exercise_id FROM workout_item) AND id NOT IN (SELECT exercise_id FROM exercise_log);
--   ALTER TABLE exercise DROP COLUMN video_url, DROP COLUMN level, DROP COLUMN laterality,
--     DROP COLUMN mechanics, DROP COLUMN zone, DROP COLUMN tags;
--   DELETE FROM flyway_schema_history WHERE version = '8';
-- =====================================================================

ALTER TABLE exercise
    ADD COLUMN video_url  VARCHAR(200),
    ADD COLUMN level      VARCHAR(20),
    ADD COLUMN laterality VARCHAR(60),
    ADD COLUMN mechanics  VARCHAR(20),
    ADD COLUMN zone       VARCHAR(60),
    ADD COLUMN tags       VARCHAR(500);

INSERT INTO exercise (name, muscle_group, level, laterality, mechanics, zone, tags, video_url, owner_id)
